"SELECT DISTINCT \nA.[Claim ID]        AS \"Claim ID\",\nCOALESCE(B.[Updated SNF Clean Claim Processed Timely],A.[SNF Clean Claim Processed Timely]) AS \"Updated SNF Clean Claim Processed Timely\",\nCOALESCE(B.[Updated Clean Claim Processed Timely],A.[Clean Claim Processed Timely]) AS \"Updated Clean Claim Processed Timely\",\nCOALESCE(B.[Updated All Claim Processed Timely],A.[All Claim Processed Timely]) AS \"Updated All Claim Processed Timely\",\nCOALESCE(B.[Updated Interest Paid Correctly],A.[Interest Paid Correctly]) AS \"Updated Interest Paid Correctly\"\nFROM [Claims Original SLA Result] AS A\nLEFT JOIN [Claims SLA Dispute Log] AS B ON A.[Claim ID] = B.[Claim ID]\n"
